.skip{position:absolute;right:12px;top:-60px;z-index:200;background:var(--brass);color:var(--ink);padding:10px 14px;border-radius:8px;font-weight:800;text-decoration:none}.skip:focus{top:12px}
:focus-visible{outline:3px solid var(--brass);outline-offset:2px}
@media (max-width:900px){.mine{grid-template-columns:1fr}.mbar{display:flex;position:fixed;bottom:0;left:0;right:0;z-index:65;background:var(--paper);border-top:1px solid var(--line);padding:6px 6px calc(6px + env(safe-area-inset-bottom,0px));box-shadow:0 -8px 20px -12px rgba(0,0,0,.3)}.mbar button{flex:1;display:flex;flex-direction:column;align-items:center;gap:2px;background:none;border:0;font-size:11px;color:var(--muted);padding:4px 0;cursor:pointer}.mbar button svg.i{width:22px;height:22px}.mbar button.on{color:var(--green);font-weight:700}.main{padding-bottom:84px!important}.bulk{bottom:78px}.cd{min-height:70px}.ce{font-size:0;height:8px;padding:0}.gs-btn kbd{display:none}.letter{position:static;box-shadow:none}}
html[data-theme=dark] :is(.ie:hover,.drop-z.on,.drop-z:hover,.sfc button){background:#2A2716!important;color:var(--text)}html[data-theme=dark] .letter{background:var(--stone)}html[data-theme=dark] .att.cur{background:#12302A}
.inst-login{display:flex;align-items:center;gap:12px;margin-top:16px;padding:12px 14px;border-radius:12px;border:1.5px dashed var(--brass);background:#FBF7EC;color:var(--ink);text-decoration:none;font-weight:700;font-size:14px;transition:background .2s,transform .2s}.inst-login:hover{background:#F5EDD8;transform:translateY(-1px)}.inst-login svg.i{width:22px;height:22px;color:var(--brass);flex-shrink:0}.inst-login small{display:block;font-weight:500;color:var(--muted);font-size:12px}

.fu-add{display:grid;grid-template-columns:200px 1fr auto;gap:8px;margin-top:10px}
.tgl{display:flex;gap:6px;margin-top:8px}.tgl button{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);color:#C9D2CE;border-radius:7px;padding:4px 9px;font-size:12px;cursor:pointer}.tgl button.on{background:rgba(176,141,60,.25);border-color:rgba(176,141,60,.6);color:#fff}
html[data-font=lg] body{zoom:1.14}

.fu-add{display:grid;grid-template-columns:200px 1fr auto;gap:8px;margin-top:10px}
.tgl{display:flex;flex-wrap:wrap;gap:5px;margin-top:8px}.tgl button{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);color:#C9D2CE;border-radius:7px;padding:3px 8px;font-size:11.5px;cursor:pointer;white-space:nowrap}.tgl button.on{background:rgba(176,141,60,.25);border-color:rgba(176,141,60,.6);color:#fff}
html[data-font=lg] body{zoom:1.14}
